<template>
  <div class="report-page">
    <header class="report-header"><div><el-tag effect="dark">AI EVALUATION REPORT</el-tag><h1>{{ isAssessmentReport ? '岗位胜任力智能评估报告' : 'AI 面试报告' }}</h1><p>{{ isAssessmentReport ? '证据驱动 · 动态能力模型 · 可解释决策' : '兼容旧面试数据生成的能力分析' }}</p></div><div><el-button @click="router.push('/user-home')">返回首页</el-button><el-button v-if="isAssessmentReport" type="primary" :loading="exporting" @click="exportPdf">导出评估报告 PDF</el-button></div></header>

    <template v-if="isAssessmentReport && report">
      <ReportSummary id="report-summary" :report="report" :job-name="session.jobProfile.name"/>
      <section id="competency-section" class="section"><div class="section-title"><span>01</span><div><h2>动态胜任力模型</h2><p>候选人得分与岗位目标线对照</p></div></div><el-card shadow="never"><CompetencyRadar :scores="report.competencyScores"/></el-card></section>
      <section id="evidence-section" class="section"><div class="section-title"><span>02</span><div><h2>证据矩阵</h2><p>评分结论可回溯到简历与面试原始证据，展开可查看来源问题</p></div></div><el-card shadow="never"><EvidenceDetail :evidence="report.evidenceSummary"/></el-card></section>
      <section id="review-section" class="section"><div class="section-title"><span>03</span><div><h2>问答复盘</h2><p>逐轮展示考察能力、AI 判断与评分变化</p></div></div><InterviewReview :reviews="report.interviewReview"/></section>
      <section id="strength-risk-section" class="section"><div class="section-title"><span>04</span><div><h2>优势与风险</h2><p>综合岗位要求识别候选人的突出能力和用人风险</p></div></div><el-row :gutter="18"><el-col :span="8"><el-card shadow="never" class="strength-card"><template #header><strong>核心优势</strong></template><div v-for="item in report.strengths" :key="item" class="strength">✓ {{ item }}</div></el-card></el-col><el-col :span="16"><RiskAnalysis :risks="report.risks"/></el-col></el-row></section>
      <section id="growth-section" class="section"><div class="section-title"><span>05</span><div><h2>发展建议</h2><p>针对能力差距生成学习建议与能力提升路线</p></div></div><GrowthPlan :plans="report.growthPlan" @train="router.push('/growth-plan')"/></section>
      <div class="footer-actions"><el-button size="large" @click="router.push('/assessment-history')">查看评估历史</el-button><el-button type="primary" size="large" @click="router.push('/growth-plan')">进入能力提升中心</el-button></div>
    </template>

    <template v-else>
      <el-alert title="当前没有岗位胜任力评估会话，已自动切换为旧面试报告模式" type="info" :closable="false" show-icon/>
      <el-card class="legacy" shadow="never"><el-descriptions :column="1" border><el-descriptions-item label="应聘岗位">{{ legacyData.jobRole || '暂无' }}</el-descriptions-item><el-descriptions-item label="创建时间">{{ legacyData.createTime || '暂无' }}</el-descriptions-item><el-descriptions-item label="AI 综合评价">{{ legacyData.aiSummary || '暂无评价' }}</el-descriptions-item></el-descriptions><h2>原六维能力分析</h2><CompetencyRadar :scores="legacyScores"/></el-card>
    </template>
  </div>
</template>

<script setup>
import { computed,onMounted,ref } from "vue";import { useRouter } from "vue-router";import { ElMessage } from "element-plus";import { jsPDF } from "jspdf";
import { getAssessmentReport } from "@/api/report";import { useAssessmentStore } from "@/store/assessment";import { useInterviewStore } from "@/store/interview";
import ReportSummary from "@/components/report/ReportSummary.vue";import CompetencyRadar from "@/components/report/CompetencyRadar.vue";import EvidenceDetail from "@/components/report/EvidenceDetail.vue";import InterviewReview from "@/components/report/InterviewReview.vue";import RiskAnalysis from "@/components/report/RiskAnalysis.vue";import GrowthPlan from "@/components/report/GrowthPlan.vue";
const router=useRouter();const assessmentStore=useAssessmentStore();const interviewStore=useInterviewStore();const session=computed(()=>assessmentStore.session);const legacyData=ref(interviewStore.reportData||{});const report=ref(null);const exporting=ref(false);const isAssessmentReport=computed(()=>Boolean(session.value.assessmentId&&session.value.competencyModel?.length));
const legacyScores=computed(()=>{const r=legacyData.value.radarData||{};return [{name:"沟通能力",score:r.communication||0,targetScore:70},{name:"技术深度",score:r.technical_depth||0,targetScore:70},{name:"问题解决",score:r.problem_solving||0,targetScore:70},{name:"学习能力",score:r.learning_ability||0,targetScore:70},{name:"团队协作",score:r.teamwork||0,targetScore:70},{name:"主动性",score:r.initiative||0,targetScore:70}].map((i,index)=>({id:`legacy-${index}`,...i,gap:i.score-i.targetScore,status:i.score>=i.targetScore?"达标":"待提升"}))});
onMounted(async()=>{if(isAssessmentReport.value){report.value=await getAssessmentReport(session.value.assessmentId,session.value);assessmentStore.setReport(report.value)}});
const safeText=(value)=>String(value||"");
const exportPdf=()=>{if(!report.value)return;exporting.value=true;try{const doc=new jsPDF();let y=18;const write=(text,size=10)=>{doc.setFontSize(size);const lines=doc.splitTextToSize(safeText(text),175);if(y+lines.length*6>280){doc.addPage();y=18}doc.text(lines,18,y);y+=lines.length*6+3};write("AI Job Competency Assessment Report",18);write(`Job: ${session.value.jobProfile.name}`,12);write(`Overall Score: ${report.value.overallScore}   Match: ${report.value.matchScore}%   Confidence: ${report.value.confidence}%`);write(`Recommendation: ${report.value.recommendation}`);write(`Summary: ${report.value.summary}`);write("Competency Scores",14);report.value.competencyScores.forEach(i=>write(`${i.name}: ${i.score}/${i.targetScore} (${i.status})`));write("Evidence",14);report.value.evidenceSummary.forEach(i=>write(`${i.competencyName}: strength ${i.strength}, confidence ${i.confidence}%, risk ${i.risk}`));write("Risks",14);report.value.risks.forEach(i=>write(`[${i.level}] ${i.title}: ${i.description}`));write("Growth Plan",14);report.value.growthPlan.forEach(i=>write(`${i.category}: ${i.action} / ${i.resource}`));doc.save(`assessment-${session.value.assessmentId}.pdf`);ElMessage.success("评估报告 PDF 已生成")}finally{exporting.value=false}};
</script>

<style>html,body{height:auto!important;overflow:visible!important;margin:0}</style>
<style scoped>.report-page{min-height:100vh;padding:34px 5%;background:#f2f5fa;color:#1d2939}.report-header{max-width:1320px;margin:0 auto 24px;display:flex;justify-content:space-between;align-items:center;padding:28px 34px;border-radius:16px;background:linear-gradient(135deg,#162b4d,#315ca8);color:white}.report-header h1{font-size:30px;margin:12px 0 6px}.report-header p{margin:0;color:#d6e4ff}.report-page>*{max-width:1320px;margin-left:auto;margin-right:auto}.section{margin-top:30px}.section-title{display:flex;align-items:center;gap:14px;margin-bottom:14px}.section-title>span{font-size:26px;font-weight:800;color:#409eff}.section-title h2{margin:0 0 4px}.section-title p{margin:0;color:#909399}.strength-card{height:166px}.strength{padding:10px;color:#529b2e;border-bottom:1px dashed #d9ecff}.footer-actions{text-align:center;padding:38px 0}.legacy{margin-top:20px}.legacy h2{text-align:center;margin-top:28px}@media(max-width:900px){.report-header{align-items:flex-start;gap:20px}.report-header,.headline{flex-direction:column}.el-col{max-width:100%;flex:0 0 100%;margin-bottom:14px}}</style>
